        if (자바도구.같음(말, "ClassCastException")) 분류코드 = 14;
        if (자바도구.같음(말, "NegativeArraySizeException")) 분류코드 = 15;
        if (분류코드 != 0 && ᎦᏘᏅᏛᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ >= 0) { 예외던짐(분류코드, 말); return; }
