    static void 건너(int ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ) { if (!ᎠᎬᎭᎸᏓ_ᏗᏓᏴᎳᏛᏙᏗ(읽기위치, ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ)) ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid attribute size"); else 읽기위치 += ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ; }
    static boolean 상검사(int 수, int 종류) {
        if (수 <= 0 || 수 >= 상종류.length || 상종류[수] != 종류) { ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid constant pool reference"); return false; }
        return true;
    }
    static boolean 구간(int ᎠᎢᏎᏍᏗ, int ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ, String 말) {
        if (!ᎠᎬᎭᎸᏓ_ᏗᏓᏴᎳᏛᏙᏗ(ᎠᎢᏎᏍᏗ, ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ)) return false;
        int 읽는자리 = ᎠᎢᏎᏍᏗ, 끝 = ᎠᎢᏎᏍᏗ + ᏱᎦᏅᎯᏓ_ᏧᎬᏩᎶᏗᏯ;
        for (int ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ = 0; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ < 말.length(); ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ++) {
            int 문자값 = 말.charAt(ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ);
            if (문자값 > 0 && 문자값 < 128) { if (읽는자리 >= 끝 || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != 문자값) return false; }
            else if (문자값 < 2048) {
                if (읽는자리 + 2 > 끝 || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != (192 | (문자값 >> 6)) || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != (128 | (문자값 & 63))) return false;
            } else if (읽는자리 + 3 > 끝 || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != (224 | (문자값 >> 12)) || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != (128 | ((문자값 >> 6) & 63)) || ᎠᏍᏆᏂᎪᏙᏗ[읽는자리++] != (128 | (문자값 & 63))) return false;
        }
        return 읽는자리 == 끝;
    }
    static boolean 말(int 상수, String 말) { return 상검사(상수, 1) && 구간(상가[상수], 상나[상수], 말); }
    static boolean 같은말(int 가, int 나) {
        if (!상검사(가, 1) || !상검사(나, 1) || 상나[가] != 상나[나]) return false;
        for (int 수 = 0; 수 < 상나[가]; 수++) if (ᎠᏍᏆᏂᎪᏙᏗ[상가[가] + 수] != ᎠᏍᏆᏂᎪᏙᏗ[상가[나] + 수]) return false;
        return true;
    }
    static int ᏄᏍᏛᎢ_ᏚᏙᎥᎢ_ᎠᎪᎵᏰᏗ(int 수) { return 상검사(수, 7) && 상검사(상가[수], 1) ? 상가[수] : 0; }
    static int 참조이름(int 수) { return 상검사(수, 12) && 상검사(상가[수], 1) ? 상가[수] : 0; }
    static int 참조형식(int 수) { return 상검사(수, 12) && 상검사(상나[수], 1) ? 상나[수] : 0; }
    static int 서술형(int 끝, boolean 빈형) {
        if (읽기위치 >= 끝) { ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid descriptor"); return 0; }
        int ᏧᎬᏩᎶᏗᏯ = byte_ᏧᎬᏩᎶᏗᏯ();
        if (ᏧᎬᏩᎶᏗᏯ == 'V' && 빈형) return 0;
        if (ᏧᎬᏩᎶᏗᏯ == 'I' || ᏧᎬᏩᎶᏗᏯ == 'B' || ᏧᎬᏩᎶᏗᏯ == 'C' || ᏧᎬᏩᎶᏗᏯ == 'S' || ᏧᎬᏩᎶᏗᏯ == 'Z') return 1;
        if (ᏧᎬᏩᎶᏗᏯ == '[') { 서술형(끝, false); return 2; }
        if (ᏧᎬᏩᎶᏗᏯ == 'L') {
            int ᎠᎢᏎᏍᏗ = 읽기위치;
            while (읽기위치 < 끝 && ᎠᏍᏆᏂᎪᏙᏗ[읽기위치] != ';') 읽기위치++;
            if (읽기위치 == 끝 || 읽기위치 == ᎠᎢᏎᏍᏗ) ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid reference descriptor");
            else 읽기위치++;
            return 2;
        }
        ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("unsupported descriptor type"); return 0;
    }
    static void 서술읽기(int ᏧᎸᏫᏍᏓᏁᏗᏱ_ᏧᎬᏩᎶᏗᏯ) {
        int 이전 = 읽기위치, 수 = 함수형[ᏧᎸᏫᏍᏓᏁᏗᏱ_ᏧᎬᏩᎶᏗᏯ];
        if (!상검사(수, 1)) return;
        읽기위치 = 상가[수]; int 끝 = 읽기위치 + 상나[수];
        if (byte_ᏧᎬᏩᎶᏗᏯ() != '(') ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid method descriptor");
        int 개수 = 0;
        while (!ᎦᎵᏓᏍᏔᏅ && 읽기위치 < 끝 && ᎠᏍᏆᏂᎪᏙᏗ[읽기위치] != ')') {
            if (개수 == 16) { ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("too many method arguments"); break; }
            함수인수형[ᏧᎸᏫᏍᏓᏁᏗᏱ_ᏧᎬᏩᎶᏗᏯ * 16 + 개수++] = 서술형(끝, false);
        }
        if (읽기위치 >= 끝 || byte_ᏧᎬᏩᎶᏗᏯ() != ')') ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid method descriptor");
        함수반환[ᏧᎸᏫᏍᏓᏁᏗᏱ_ᏧᎬᏩᎶᏗᏯ] = 서술형(끝, true); 함수인수수[ᏧᎸᏫᏍᏓᏁᏗᏱ_ᏧᎬᏩᎶᏗᏯ] = 개수;
        if (읽기위치 != 끝) ᎤᏄᎸᎲᎦ_ᏧᎬᏩᎶᏗᏯ("invalid method descriptor");
        읽기위치 = 이전;
    }
    static int 상번호() { int ᏧᎬᏩᎶᏗᏯ = 짧은수(); return ᏧᎬᏩᎶᏗᏯ == 0 ? 0 : 현재읽는종 * 512 + ᏧᎬᏩᎶᏗᏯ; }
