                for (int 안쪽자리 = 0; 안쪽자리 < 함수지역[ᎦᏘᏅᏛᏙᏗ_method[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]]; 안쪽자리++) if (지역형[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ * 128 + 안쪽자리] == 2) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(ᎡᏍᎦᏂ_ᏧᎬᏩᎶᏗᏯ[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ * 128 + 안쪽자리]);
                for (int 안쪽자리 = 0; 안쪽자리 < 틀스택[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]; 안쪽자리++) if (스택형[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ * 128 + 안쪽자리] == 2) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(스택값[ᎠᏍᏆᏂᎪᏙᏗ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ * 128 + 안쪽자리]);
