        for (int ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ = 0; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ < 나중수; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ++) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(나중실행[ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]);
        for (int ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ = 0; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ < Store_integer.length; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ++) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(Store_integer[ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]);
        for (int ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ = 0; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ < 종수; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ++) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(종잠금[ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]);
        for (int 검사자리 = 1; 검사자리 < 힙끝; 검사자리 += 힙폭[검사자리]) if (잠금깊이[검사자리] > 0) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(검사자리);
        ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(던진객체);
        for (int ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ = 0; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ < 잠시수; ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ++) ᏍᎩᎪᏩᏛᏓ_ᏧᎬᏩᎶᏗᏯ(잠시참조[ᎬᎪᏘᎶᏓ_ᏂᎬᎿᏅ_ᎠᏓᏎᎮᎯ]);
